targets.query:
from(bucket: "energy")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "haven.airquality" and r._field == "tvoc_ppb")

from(bucket: "energy")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "hvac.overrides" and (r._field == "delta_cool_f" or r._field == "delta_heat_f"))
